+/// Effective contact = corrected value when present, else the
+/// snapshot (AD-7). A corrected '' is treated as absent (falls back to the
+/// snapshot).
+fn effective_contact(
+  corrected: Option(String),
+  snapshot: Option(String),
+) -> Option(String) {
+  case corrected {
+    Some(c) -> opt_nonempty(c)
+    None -> snapshot
+  }
+}
